import {METRICS,TODAY,numeric,bmi,emergency,validateMeasurement,trend,preliminaryEligibility,parseCSV,parseFHIR,validDate,validateBloodPressure} from './core.js';
const paths={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z M3 11h4l2-4 4 9 2-5h6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',clipboard:'M9 4H5v17h14V4h-4 M9 2h6v4H9z M8 11h8 M8 15h5',history:'M3 11a9 9 0 1 1 2.6 7 M3 4v7h7 M12 7v5l3 2',chart:'M3 3v18h18 M6 15l4-5 4 3 6-7',activity:'M2 12h5l3-8 4 16 3-8h5',file:'M14 2H5v20h14V7z M14 2v5h5 M8 12h8 M8 16h6',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-3a8 5 0 0 1 16 0v3',users:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 5 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 8 M18 16a5 4 0 0 1 4 4v1',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',arrow:'M5 12h14 M14 7l5 5-5 5',up:'M6 17 18 5 M6 5h12v12',down:'M6 7l6 6 6-6',chevron:'M9 5l7 7-7 7',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',logout:'M9 3H3v18h6 M10 12h11 M17 8l4 4-4 4',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 11v6 M12 7h.01',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z M20 2v4 M18 4h4',droplet:'M12 2S5 10 5 14a7 7 0 0 0 14 0c0-4-7-12-7-12',scale:'M7 3h10l4 18H3z M9 7h6 M12 7v4',check:'M5 12l4 4L20 5',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18',search:'M21 21l-5-5 M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',close:'M6 6l12 12 M6 18 18 6',menu:'M3 6h18 M3 12h18 M3 18h18',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',warning:'M12 3 2 21h20z M12 9v5 M12 17h.01',edit:'M14 5l5 5 M4 20l5-1L21 7l-5-5L4 14z',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 6v6l4 2',external:'M14 3h7v7 M10 14 21 3 M10 3H3v18h18v-7',book:'M12 5C8 2 3 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-1-1-6-2-10 1Z M12 5v16'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.activity}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brand=()=>`<a href="#/home" class="brand" aria-label="CardioLens AI home"><div class="brand-mark">${icon('heart')}</div><div class="brand-name">CardioLens<span>AI</span></div></a>`;
const sampleYears=[{year:2022,systolic_bp:122,diastolic_bp:78,ldl:101,hdl:52,bmi:23.8,weight:70.4,hba1c:5.5,heart_rate:68,total_cholesterol:190,egfr:98},{year:2023,systolic_bp:128,diastolic_bp:80,ldl:112,hdl:50,bmi:24.7,weight:73.1,hba1c:5.7,heart_rate:70,total_cholesterol:202,egfr:94},{year:2024,systolic_bp:136,diastolic_bp:84,ldl:131,hdl:47,bmi:26.4,weight:78.1,hba1c:6,heart_rate:73,total_cholesterol:219,egfr:90},{year:2025,systolic_bp:142,diastolic_bp:88,ldl:148,hdl:45,bmi:28.1,weight:83.1,hba1c:6.2,heart_rate:76,total_cholesterol:236,egfr:87},{year:2026,systolic_bp:151,diastolic_bp:94,ldl:164,hdl:43,bmi:29.3,weight:86.7,hba1c:6.4,heart_rate:79,total_cholesterol:248,egfr:82}];
const sampleRecords=()=>sampleYears.flatMap(y=>Object.entries(y).filter(([k])=>k!=='year').map(([type,value])=>({id:`demo-${y.year}-${type}`,type,value,unit:METRICS[type].unit,recorded_at:`${y.year}-04-14`,source:'sample',verified:false})));
const defaultState=()=>({role:'patient',sample:true,profile:{name:'Alex Morgan',age:54,sex:'male',height:172,weight:86.7,diabetes:false,hypertension:true,smoking:'Never',exercise:'3 days / week',sleep:7,stress:'Moderate'},records:sampleRecords(),notes:{},reports:[],audits:[],selectedPatient:'p1'});
function restoreSession(saved){if(!saved||typeof saved!=='object')return defaultState();const profile=saved.profile&&typeof saved.profile==='object'&&!Array.isArray(saved.profile)?{...saved.profile}:{};profile.name=typeof profile.name==='string'&&profile.name.trim()?profile.name.trim().slice(0,80):'Your profile';profile.sex=typeof profile.sex==='string'?profile.sex:'Unknown';for(const key of [...Object.keys(METRICS),'age','height','sleep'])if(key in profile)profile[key]=numeric(profile[key]);const records=(Array.isArray(saved.records)?saved.records:[]).flatMap(r=>{try{return [{...validateMeasurement(r),id:typeof r.id==='string'?r.id:crypto.randomUUID(),source:typeof r.source==='string'?r.source:'manual'}];}catch{return [];}});const notes=Object.fromEntries(Object.entries(saved.notes&&typeof saved.notes==='object'?saved.notes:{}).filter(([,v])=>typeof v==='string'));const reports=(Array.isArray(saved.reports)?saved.reports:[]).filter(r=>r&&typeof r.name==='string'&&typeof r.html==='string'&&numeric(r.count)!==null&&typeof r.created_at==='string'&&!Number.isNaN(Date.parse(r.created_at)));const audits=(Array.isArray(saved.audits)?saved.audits:[]).filter(a=>a&&typeof a.action==='string'&&typeof a.detail==='string'&&!Number.isNaN(Date.parse(a.time)));return {role:['patient','doctor','admin'].includes(saved.role)?saved.role:'patient',sample:saved.sample===true,profile,records,notes,reports,audits,selectedPatient:/^p[1-6]$/.test(saved.selectedPatient)?saved.selectedPatient:'p1'};}
let state=defaultState();try{const saved=JSON.parse(sessionStorage.getItem('cardiolens-session'));if(saved)state=restoreSession(saved);}catch{}
let route='dashboard',metric='systolic_bp',period=5,selectedYear=2026,historyFilter='all',doctorFilter='all',doctorSearch='',doctorSort='risk',activePatient=state.selectedPatient||'p1',noteDrafts={},formStep=0,draft={},draftSymptoms={},staged=[],thresholds=null;
const patients=[{id:'p1',name:'Alex Morgan',age:54,sex:'Male',risk:18.4,category:'Elevated',trend:'Increasing',review:'Required',initials:'AM',color:'amber'},{id:'p2',name:'Sarah Chen',age:46,sex:'Female',risk:9.2,category:'Moderate',trend:'Increasing',review:'Suggested',initials:'SC',color:'blue'},{id:'p3',name:'James Wilson',age:61,sex:'Male',risk:26.1,category:'Very high',trend:'Increasing',review:'Required',initials:'JW',color:'amber'},{id:'p4',name:'Maya Patel',age:39,sex:'Female',risk:3.6,category:'Low',trend:'Stable',review:'Routine',initials:'MP',color:'teal'},{id:'p5',name:'Daniel Brooks',age:57,sex:'Male',risk:16.8,category:'Elevated',trend:'Decreasing',review:'Suggested',initials:'DB',color:'amber'},{id:'p6',name:'Olivia Martin',age:43,sex:'Female',risk:4.1,category:'Low',trend:'Stable',review:'Routine',initials:'OM',color:'teal'}];
const menu={patient:[['dashboard','grid','Overview'],['assessment','clipboard','Health assessment'],['history','history','Medical history'],['timeline','chart','Health timeline'],['risk','activity','Risk analysis'],['reports','file','Reports'],['profile','user','My profile']],doctor:[['doctor','grid','Overview'],['patients','users','My patients'],['monitor','activity','Risk monitor'],['doctor-reports','file','Reports']],admin:[['models','chart','Model performance'],['versions','settings','Model versions'],['audit','history','Audit logs']]};
const persist=()=>{try{sessionStorage.setItem('cardiolens-session',JSON.stringify(state));}catch{toast('Session storage is unavailable; changes will last until this page closes.');}};
function audit(action,detail=''){state.audits.unshift({time:new Date().toISOString(),action,detail});persist();}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4300);}
function latest(type,records=state.records){return records.filter(r=>r.type===type).sort((a,b)=>a.recorded_at.localeCompare(b.recorded_at)).at(-1);}
function fmt(v){return numeric(v)===null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:1});}
function dateLabel(date){return new Date(date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}
function name(){return state.profile.name||'Your profile';}
function initials(n=name()){return n.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function badge(text,color='neutral'){return `<span class="badge ${color}">${esc(text)}</span>`;}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions">${actions}</div></div>`;}
function btn(label,action,ico='',primary=false){return `<button class="btn${primary?' primary':''}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;}
function banner(text,kind='',ico='info'){return `<div class="banner ${kind}">${icon(ico)}<div>${text}</div></div>`;}
function sampleNotice(){return banner('Illustrative patient data and predictions. No trained model is connected; sample scores must not guide clinical decisions.');}
function completeness(){const fields=['systolic_bp','diastolic_bp','ldl','hdl','bmi','weight','hba1c','heart_rate','total_cholesterol','egfr','triglycerides','glucose','creatinine','uacr'];const missing=fields.filter(k=>!latest(k));const have=fields.length-missing.length+(numeric(state.profile.age)!==null?1:0);return {percent:Math.round(have/15*100),missing:[...(numeric(state.profile.age)===null?['age']:[]),...missing]};}
function shell(content){const nav=menu[state.role]||menu.patient;const current=nav.find(x=>x[0]===route)?.[2]||(route==='patient-detail'?'Patient details':route==='evidence'?'Evidence & limitations':'Account');const displayName=state.role==='doctor'?'Dr. Taylor Reed':state.role==='admin'?'Model administrator':name();return `<div class="mobile-overlay" data-action="close-nav"></div><aside class="sidebar">${brand()}<div class="workspace">${icon(state.role==='doctor'?'users':state.role==='admin'?'shield':'heart')}<select aria-label="Switch demo workspace" id="role-switch"><option value="patient" ${state.role==='patient'?'selected':''}>Patient workspace</option><option value="doctor" ${state.role==='doctor'?'selected':''}>Doctor workspace</option><option value="admin" ${state.role==='admin'?'selected':''}>Model administration</option></select></div><div class="nav-label">WORKSPACE</div><nav class="nav">${nav.map(([id,ico,label])=>`<a href="#/${id}" class="${route===id||(id==='patients'&&route==='patient-detail')?'active':''}">${icon(ico)}<span>${label}</span>${id==='reports'&&state.reports.length?`<span class="nav-count">${state.reports.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card">${icon('shield')}<h3>Care, with perspective.</h3><p>Your health story is more than a single number.</p><a href="#/evidence">How CardioLens works ${icon('arrow')}</a></div><div class="sidebar-user"><div class="avatar">${initials(displayName)}</div><div><div class="user-name">${esc(displayName)}</div><div class="user-meta">${state.role==='patient'?'Personal workspace':'Demonstration access'}</div></div><button data-action="account" title="Account" aria-label="Account">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="flex gap"><button class="icon-btn menu-btn" data-action="open-nav" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb">${state.role==='patient'?'My health':state.role==='doctor'?'Clinical workspace':'Administration'} <span>/ &nbsp; ${current}</span></div></div><div class="top-actions"><a href="#/home" class="small muted">About CardioLens</a><div class="demo-pill"><i class="dot"></i> Prototype</div><button class="icon-btn notification" data-action="notifications" aria-label="View notifications">${icon('bell')}</button><div class="top-avatar"><div class="avatar">${initials(displayName)}</div></div></div></header><main id="main" class="main" tabindex="-1">${content}<footer class="footer"><span>${icon('shield')} Clinical decision support prototype · Not an autonomous diagnosis or emergency tool</span><a href="#/evidence">Evidence & limitations ${icon('external')}</a></footer></main></div>`;}
function metricCard(type,ico){const l=latest(type);const t=trend(state.records,type);const value=type==='systolic_bp'?`${fmt(l?.value)}<span style="display:inline;font-size:22px;color:var(--ink);margin:0">/${fmt(latest('diastolic_bp')?.value)}</span>`:fmt(l?.value);return `<section class="card metric-card"><div class="metric-title">${METRICS[type].short}<div class="metric-icon">${icon(ico)}</div></div><div class="metric-number">${value}<span>${METRICS[type].unit}</span></div><div class="metric-bottom">${t?`${icon(t.change>=0?'up':'chart')}${t.change>0?'+':''}${fmt(t.change)}<span>over ${t.period_label}</span>`:'<span>Add records to see a trend</span>'}</div></section>`;}
function riskCard(){return `<section class="card risk-card"><div class="section-label">${icon('heart')} Cardiovascular risk ${badge(state.sample?'Sample':'Unavailable')}</div><div class="gauge"><svg viewBox="0 0 220 150" role="img" aria-label="${state.sample?'Illustrative 10-year risk, 18.4 percent; scale zero to one hundred percent':'Risk estimate unavailable'}"><path d="M25 118 A85 85 0 1 1 195 118" fill="none" stroke="#e9eff0" stroke-width="10" stroke-linecap="round"/><path d="M25 118 A85 85 0 1 1 195 118" fill="none" stroke="#7da6a1" stroke-width="10" stroke-linecap="round" pathLength="100" stroke-dasharray="${state.sample?'18.4 100':'0 100'}"/><text x="21" y="142" font-size="9" fill="#98a4aa">0%</text><text x="179" y="142" font-size="9" fill="#98a4aa">100%</text></svg><div class="gauge-center"><div class="risk-number">${state.sample?'18.4<span>%</span>':'—'}</div><p>10-year estimate · ${state.sample?'illustrative':'not calculated'}</p></div></div><div class="risk-tag">${badge(state.sample?`${thresholds?.bands.find(b=>.184>=b.min&&.184<b.max)?.label||'Uncategorized'} · example category`:'Model not connected',state.sample?'amber':'neutral')}</div><div class="risk-detail"><span class="muted">Risk trajectory</span><span>${state.sample?`${icon('up')} Increasing · sample`:'Unavailable'}</span></div><div class="risk-detail"><span class="muted">Model confidence</span><span>Not measured</span></div><div class="risk-bottom"><span>${state.sample?'Example · 14 Apr 2026':'No validated prediction'}</span><a class="link-btn" href="#/risk">Details ${icon('arrow')}</a></div></section>`;}
function chart(records=state.records,compact=false){let r=records.filter(x=>x.type===metric).sort((a,b)=>a.recorded_at.localeCompare(b.recorded_at));if(r.length){const cutoff=Number(r.at(-1).recorded_at.slice(0,4))-period+1;r=r.filter(x=>Number(x.recorded_at.slice(0,4))>=cutoff);}if(!r.length)return `<div class="empty">${icon('chart')}<h3>No ${METRICS[metric].short.toLowerCase()} records yet</h3><p>Add a dated measurement to start your timeline.</p>${btn('Add a measurement','add-record','plus')}</div>`;const w=650,h=220,left=40,right=20,top=24,bottom=35;let lo=Math.floor(Math.min(...r.map(x=>x.value))*.85/5)*5,hi=Math.ceil(Math.max(...r.map(x=>x.value))*1.1/5)*5;if(hi===lo)hi+=5;if(['bmi','hba1c'].includes(metric)){lo=Math.floor(Math.min(...r.map(x=>x.value))-1);hi=Math.ceil(Math.max(...r.map(x=>x.value))+1);}const dateMin=Date.parse(r[0].recorded_at),dateMax=Date.parse(r.at(-1).recorded_at);const x=i=>r.length===1?(w+left-right)/2:left+(Date.parse(r[i].recorded_at)-dateMin)/(dateMax-dateMin||1)*(w-left-right);const y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom);const coords=r.map((d,i)=>`${x(i)},${y(d.value)}`).join(' ');const line=`M${coords.replace(/ /g,' L')}`;const fill=`${line} L${x(r.length-1)},${h-bottom} L${x(0)},${h-bottom} Z`;let ticks='';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;ticks+=`<line class="gridline" x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}"/><text x="${left-10}" y="${y(v)+3}" text-anchor="end">${fmt(v)}</text>`;}const stride=Math.max(1,Math.ceil(r.length/6));return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(METRICS[metric].label)} over time"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#74a5a0" stop-opacity=".15"/><stop offset="100%" stop-color="#74a5a0" stop-opacity=".01"/></linearGradient></defs>${ticks}<path d="${fill}" fill="url(#chart-fill)"/><path d="${line}" fill="none" stroke="#62938f" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${r.map((d,i)=>`${i%stride===0||i===r.length-1?`<text x="${x(i)}" y="${h-8}" text-anchor="middle">${r.length<=5?d.recorded_at.slice(0,4):d.recorded_at.slice(2)}</text>`:''}<circle class="chart-point" cx="${x(i)}" cy="${y(d.value)}" r="4" fill="#fff" stroke="#62938f" stroke-width="2" tabindex="0" aria-label="${dateLabel(d.recorded_at)}: ${d.value} ${esc(d.unit)}" data-record="${esc(d.id)}"><title>${dateLabel(d.recorded_at)}: ${d.value} ${esc(d.unit)} · ${d.source}</title></circle>`).join('')}</svg>`;}
function chartCard(title='Your health, over time',records=state.records){return `<section class="card chart-card"><div class="card-title"><div><h2>${title}</h2><p>A clearer picture starts with your history.</p></div><div class="segmented" aria-label="Timeline range">${[1,3,5].map(p=>`<button data-period="${p}" class="${period===p?'active':''}">${p}Y</button>`).join('')}</div></div><div class="chart-controls"><select id="chart-metric" aria-label="Choose health measurement">${Object.entries(METRICS).map(([k,v])=>`<option value="${k}" ${metric===k?'selected':''}>${v.short}</option>`).join('')}</select><div class="legend"><span><i style="background:#62938f"></i>${esc(METRICS[metric].unit)}</span><span><i style="background:#c3cecd"></i>${records.some(r=>r.source==='sample')?'Sample records':'Entered records'}</span></div></div>${chart(records)}<div class="chart-footer">${icon('info')} Select a point to inspect its measurement and source.</div></section>`;}
function factorCard(){return `<section class="card factor-card"><div class="card-title"><div><h2>What’s shaping the picture?</h2><p>Changes observed in your health records</p></div>${icon('spark')}</div><div class="factor-list">${[['systolic_bp','activity'],['ldl','droplet'],['bmi','scale'],['hba1c','clipboard']].map(([type,ico])=>{const t=trend(state.records,type);return `<div class="factor-row"><div class="factor-icon">${icon(ico)}</div><div class="factor-info"><strong>${METRICS[type].short}</strong><p>${t?`${fmt(t.base.value)} → ${fmt(t.latest.value)} ${METRICS[type].unit}`:'More records needed'}</p></div><span class="trend-mini">${t?`${t.change>0?'+':''}${fmt(t.change)}`:'—'}</span></div>`;}).join('')}</div><div class="factor-note">These are measured trends, not model feature contributions. SHAP explanations will appear when a validated model is connected.</div><a href="#/risk" class="link-btn">Explore your assessment ${icon('arrow')}</a></section>`;}
function recentTable(){const unique=Object.values(Object.fromEntries([...state.records].sort((a,b)=>a.recorded_at.localeCompare(b.recorded_at)).map(r=>[r.type,r]))).sort((a,b)=>b.recorded_at.localeCompare(a.recorded_at)).slice(0,3);return `<section class="card records-card"><div class="card-title"><div><h2>Recent health records</h2><p>Your latest measurements, in one place</p></div><a href="#/history" class="link-btn">View all ${icon('arrow')}</a></div><div class="table-wrap"><table><thead><tr><th>MEASUREMENT</th><th>RESULT</th><th>RECORDED</th><th>SOURCE</th></tr></thead><tbody>${unique.length?unique.map(r=>`<tr><td><span class="table-icon">${icon(r.type==='ldl'?'droplet':'activity')}</span><strong>${METRICS[r.type].short}</strong></td><td>${fmt(r.value)} <span class="muted">${esc(r.unit)}</span></td><td class="muted">${dateLabel(r.recorded_at)}</td><td>${badge(r.source==='sample'?'Sample':'Unverified','neutral')}</td></tr>`).join(''):'<tr><td colspan="4">No measurements yet. Add your first health record.</td></tr>'}</tbody></table></div></section>`;}
function completeCard(){const c=completeness();return `<section class="card complete-card"><h2>A more complete picture</h2><p class="small muted" style="margin-top:4px">Assessment data completeness</p><div class="complete-top"><div class="complete-number">${c.percent}<span>%</span></div>${badge(c.missing.length?'Room to improve':'Complete',c.missing.length?'neutral':'teal')}</div><div class="progress"><div style="width:${c.percent}%"></div></div><p class="tiny muted">${c.missing.length?'Useful information still missing:':'All tracked measurements are present. This does not establish model reliability.'}</p><div class="missing-chips">${c.missing.slice(0,4).map(k=>`<span>${esc(METRICS[k]?.short||'Age')}</span>`).join('')}</div><a href="#/assessment" class="btn">Complete health information ${icon('arrow')}</a></section>`;}
function dashboard(){return heading(`Your health, in perspective.`,`Welcome back, ${esc(name().split(' ')[0])}. Let’s look at the bigger picture.`,btn('Download report','download','download')+btn('Update assessment','assessment','plus',true))+`<div class="overview-grid">${riskCard()}${metricCard('systolic_bp','activity')}${metricCard('ldl','droplet')}${metricCard('bmi','scale')}<div class="insight-strip"><div class="insight-icon">${icon('spark')}</div><div><h3>${state.sample?'Your history tells a story.':'Build your health story.'}</h3><p>${state.sample?'Blood pressure, LDL and BMI have increased across five years of sample records. A clinician can help interpret these changes in context.':'Record measurements over time to see changes. Risk estimates will remain unavailable until a validated prediction service is connected.'}</p></div><a href="#/timeline">View timeline ${icon('arrow')}</a></div></div><div class="dashboard-lower">${chartCard()}${factorCard()}</div><div class="dashboard-bottom">${recentTable()}${completeCard()}</div><div style="margin-top:18px">${state.sample?sampleNotice():banner('Your entries stay in this browser session. This prototype has no secure clinical backend or trained prediction model.')}</div>`;}
function home(){const previousMetric=metric,previousPeriod=period;metric='systolic_bp';period=5;const heroChart=chart(sampleRecords());metric=previousMetric;period=previousPeriod;const features=[['history','Longitudinal analysis','Follow changes in your health across years, with dated records and a clear cardiovascular timeline.'],['activity','Risk intelligence','Explore a preview of future clinical and research risk outputs, with uncertainty made visible.'],['spark','Explainable insights','Understand observed trends. Model-generated explanations require a validated model.'],['clipboard','Clinical risk scores','Screen eligibility before applying a validated equation. Calculator integration is pending.'],['users','A clinician’s perspective','Review a demonstration patient list, inspect records and keep clinical notes.'],['shield','Records you control','Review imported values before saving. This demo uses browser-session storage.']];return `<div class="landing"><header class="landing-header">${brand()}<nav class="landing-nav"><a href="#features">The platform</a><a href="#/evidence">Our approach</a><a href="#/login" class="btn">Doctor login ${icon('arrow')}</a></nav></header><main id="main" tabindex="-1"><section class="hero"><div><div class="badge teal">${icon('heart')} Built around your health story</div><h1>Understand the past.<br><em>See the bigger picture.</em></h1><p>Understand the past. Predict cardiovascular risk earlier. Bring years of health records together to see patterns, understand changes, and support better conversations with your clinician.</p><div class="page-actions"><a class="btn primary large" href="#/assessment">Start assessment ${icon('arrow')}</a><a class="btn large" href="#/dashboard">Explore the demo</a></div><div class="hero-foot"><span>${icon('history')} Years of context</span><span>${icon('shield')} Clinician-led decisions</span></div></div><div class="hero-preview"><div class="preview-top"><span>CARDIOLENS · HEALTH OVERVIEW</span><span>ILLUSTRATIVE DEMO</span></div><div class="preview-inner"><div class="between"><span class="eyebrow">Your health trajectory</span>${badge('2022 — 2026','teal')}</div><div style="margin-top:18px" class="between"><div><div class="risk-number">18.4<span>%</span></div><p class="tiny muted" style="margin-top:5px">Illustrative 10-year risk · not a prediction</p></div>${icon('heart')}</div>${heroChart}<div class="preview-measures"><div><strong>151/94</strong><span>Blood pressure · mmHg</span></div><div><strong>164</strong><span>LDL · mg/dL</span></div><div><strong>29.3</strong><span>Body mass index</span></div></div></div><div class="floating-tag">${icon('history')} Five years. One clearer picture.</div></div></section><section class="feature-section" id="features"><div class="feature-heading"><div class="eyebrow">Connected context. Considered care.</div><h2 style="margin-top:10px">More than a moment in time.</h2><p>Understand your cardiovascular health with the context it deserves.</p></div><div class="feature-grid">${features.map(([ico,title,text])=>`<article class="card feature-item">${icon(ico)}<h3>${title}</h3><p>${text}</p></article>`).join('')}</div><div class="mt">${sampleNotice()}</div></section></main><footer class="landing-footer"><span>© 2026 CardioLens AI · Clinical decision-support prototype</span><a href="#/evidence">Evidence, model status & limitations ${icon('arrow')}</a></footer></div>`;}
function recordRows(records){return records.map(r=>`<tr><td><strong>${METRICS[r.type]?.short||esc(r.type)}</strong></td><td>${fmt(r.value)} <span class="muted">${esc(r.unit)}</span></td><td>${dateLabel(r.recorded_at)}</td><td>${badge(r.source==='sample'?'Sample':r.source,'neutral')}</td><td>${badge('Unverified','neutral')}</td><td><div class="row-actions"><button data-inspect="${esc(r.id)}" aria-label="Inspect ${esc(METRICS[r.type]?.short)}">${icon('info')}</button>${r.source!=='sample'?`<button data-edit="${esc(r.id)}" aria-label="Edit measurement">${icon('edit')}</button><button data-delete="${esc(r.id)}" aria-label="Delete measurement">${icon('trash')}</button>`:''}</div></td></tr>`).join('');}
function history(){const records=state.records.filter(r=>historyFilter==='all'||r.type===historyFilter).sort((a,b)=>b.recorded_at.localeCompare(a.recorded_at));return heading('Medical history','The details behind your health story.',btn('Import records','upload','upload')+btn('Add measurement','add-record','plus',true))+`<div class="filter-row"><select id="history-filter" aria-label="Filter measurements"><option value="all">All measurements</option>${Object.entries(METRICS).map(([k,v])=>`<option value="${k}" ${historyFilter===k?'selected':''}>${v.short}</option>`).join('')}</select><span class="small muted">${records.length} records · all entries include date, unit and source</span></div><section class="card table-wrap"><table><thead><tr><th>MEASUREMENT</th><th>VALUE</th><th>RECORDED</th><th>SOURCE</th><th>VERIFICATION</th><th></th></tr></thead><tbody>${recordRows(records)||'<tr><td colspan="6">No records match this selection.</td></tr>'}</tbody></table></section><div class="two-col mt"><section class="card card-pad"><h2>Conditions & history</h2><div class="details-list">${[['Hypertension',state.profile.hypertension],['Diabetes',state.profile.diabetes],['Kidney disease',state.profile.kidney_disease],['Previous heart disease',state.profile.previous_heart_disease],['Previous stroke',state.profile.previous_stroke],['Family history',state.profile.family_history]].map(([k,v])=>`<div><span>${k}</span><span>${v===undefined?'Not entered':v?'Reported':'Not reported'}</span></div>`).join('')}</div><a href="#/assessment" class="link-btn mt">Update medical information ${icon('arrow')}</a></section><section class="card card-pad"><h2>Medications & care history</h2><div class="details-list">${[['Current medications',state.profile.medications],['Previous medications',state.profile.previous_medications],['Hospital admissions',state.profile.admissions],['Previous surgeries',state.profile.surgeries]].map(([k,v])=>`<div><span>${k}</span><span>${esc(v||'Not entered')}</span></div>`).join('')}</div><p class="tiny muted mt">Patient-reported information needs clinical verification.</p></section></div>`;}
function timeline(){const years=[...new Set(state.records.map(r=>Number(r.recorded_at.slice(0,4))))].sort();if(!years.includes(selectedYear))selectedYear=years.at(-1);const yearRecords=state.records.filter(r=>Number(r.recorded_at.slice(0,4))===selectedYear);return heading('Every year adds perspective.','Explore how your measurements have changed over time.',btn('Add a record','add-record','plus',true))+chartCard('Your cardiovascular timeline')+`<section class="card card-pad mt"><div class="card-title"><h2>A closer look at ${selectedYear||'your history'}</h2>${badge(state.sample?'Sample history':'Entered history')}</div><div class="timeline-track">${years.map(y=>`<button class="year-node ${y===selectedYear?'active':''}" data-year="${y}"><i></i>${y}<span>${state.records.filter(r=>Number(r.recorded_at.slice(0,4))===y).length} measurements</span></button>`).join('')}</div><div class="timeline-detail">${['systolic_bp','ldl','bmi','hba1c','heart_rate'].map(t=>`<p>${METRICS[t].short}<strong>${fmt(latest(t,yearRecords)?.value)} <small class="tiny muted">${METRICS[t].unit}</small></strong></p>`).join('')}</div><div class="table-wrap mt"><table><thead><tr><th>MEASUREMENT</th><th>VALUE</th><th>RECORDED</th><th>SOURCE</th><th>VERIFICATION</th><th></th></tr></thead><tbody>${recordRows(yearRecords)||'<tr><td colspan="6">Add a dated measurement to begin.</td></tr>'}</tbody></table></div></section>`;}
function risk(){const eligibility=preliminaryEligibility(state.profile);return heading('Understand the assessment.','Transparent outputs, with the context and limitations you need.',btn('Download report','download','download')+btn('Review information','assessment','clipboard',true))+`${state.sample?sampleNotice():banner('A risk number cannot be calculated: no validated clinical calculator or trained research model is connected.')}<div class="three-col mt"><section class="card card-pad"><div class="section-label">${icon('clipboard')} Clinical risk engine</div><div class="stats-value">—</div><h3>Calculator unavailable</h3><p class="small muted mt">${esc(eligibility.reason)}</p>${badge(eligibility.eligible?'Initial screen only':'Eligibility check failed',eligibility.eligible?'neutral':'amber')}<a class="evidence-link" href="https://professional.heart.org/en/guidelines-and-statements/about-prevent-calculator" target="_blank" rel="noopener">AHA PREVENT population & requirements ↗</a></section><section class="card card-pad"><div class="section-label">${icon('activity')} Research model</div><div class="stats-value">${state.sample?'18.4<small style="font-size:18px">%</small>':'—'}</div><h3>${state.sample?'Illustrative output only':'Prediction unavailable'}</h3><p class="small muted mt">No model has been trained, calibrated or externally validated. The example is fictional.</p><div class="mt">${badge('Not for clinical use','amber')}</div></section><section class="card card-pad"><div class="section-label">${icon('shield')} Reliability</div><div class="stats-value">—</div><h3>Confidence not measured</h3><p class="small muted mt">Data completeness is ${completeness().percent}%. Completeness is not predictive confidence.</p><div class="mt">${badge('Validation pending','neutral')}</div></section></div><div class="two-col mt">${factorCard()}<section class="card card-pad"><h2>What the records show</h2><p class="small muted mt">${state.records.length?'Changes below are calculated from dated measurements, without generating a medical diagnosis.':'Enter at least two dated measurements to calculate a trend.'}</p><div class="details-list">${['systolic_bp','ldl','bmi','hba1c'].map(t=>{const v=trend(state.records,t);return `<div><span>${METRICS[t].short}</span><strong>${v?`${v.change>0?'+':''}${fmt(v.change)} ${METRICS[t].unit} / ${v.period_label}`:'Insufficient history'}</strong></div>`;}).join('')}</div><p class="small muted mt">Discuss these records with a clinician. This prototype does not recommend treatment or determine whether a patient is safe.</p></section></div><section class="card card-pad mt"><h2>Designed for accountable prediction</h2><div class="pipeline"><span>Validated data</span>${icon('arrow')}<span>Clinical equation + research model</span>${icon('arrow')}<span>Calibration & uncertainty</span>${icon('arrow')}<span>Actual feature contributions</span>${icon('arrow')}<span>Clinician review</span></div><p class="tiny muted mt">The prediction pipeline is planned. This interface currently implements record validation and trend calculations only.</p></section>`;}
const steps=['Symptoms & safety','Basic information','Cardiovascular health','Blood tests','Lifestyle & history','Review & save'];
function inputField(key,label,unit='',min='',max='',optional=true,type='number'){const val=draft[key];return `<div class="field"><label for="${key}">${label}${unit?` <small>${unit}</small>`:''}</label><div class="input-unit"><input id="${key}" name="${key}" type="${type}" ${type==='number'?`step="any" min="${min}" max="${max}"`:''} value="${esc(val??'')}" ${optional?'': 'required'} ${draft[key]===null?'disabled':''}>${unit?`<span>${unit}</span>`:''}</div>${optional?`<label class="unknown-label"><input type="checkbox" data-unknown="${key}" aria-label="${esc(label)} unknown or unavailable" ${draft[key]===null?'checked':''}> Unknown / unavailable</label>`:''}</div>`;}
function selectField(key,label,options){return `<div class="field"><label for="${key}">${label}</label><select id="${key}" name="${key}">${options.map(v=>`<option value="${v}" ${draft[key]===v?'selected':''}>${v}</option>`).join('')}</select></div>`;}
function checkField(key,label,source=draft){return `<label class="check"><input type="checkbox" name="${key}" ${source[key]?'checked':''}>${label}</label>`;}
function assessment(){let content='';if(emergency(draftSymptoms))return heading('Urgent medical attention recommended.','The assessment is paused because emergency symptoms were selected.')+`<div class="banner emergency">${icon('warning')}<div><h2>These symptoms may need immediate medical evaluation.</h2><p>Contact your local emergency services now if you have severe chest pain, severe shortness of breath, or fainting. Do not rely on a CardioLens risk score for emergency symptoms.</p><p>No risk score has been calculated. This symptom check cannot rule out an emergency.</p><button class="btn danger mt" data-action="review-symptoms">Correct symptom entries</button></div></div><a class="evidence-link" href="https://www.nhs.uk/conditions/heart-attack/" target="_blank" rel="noopener">NHS: heart attack symptoms and urgent help ↗</a>`;
if(formStep===0)content=`<h2>First, a quick safety check.</h2><p>Are you experiencing any of these symptoms now?</p><div class="check-grid">${[['severe_chest_pain','Severe chest pain'],['severe_breathlessness','Severe shortness of breath'],['fainting','Fainting'],['chest_pain','Other chest discomfort'],['breathlessness','Other breathlessness'],['palpitations','Palpitations'],['dizziness','Dizziness'],['fatigue','Fatigue'],['swelling','Swelling']].map(([k,l])=>checkField(k,l,draftSymptoms)).join('')}</div><div class="mt">${banner('Emergency symptoms stop this assessment before any score is shown. If you think you may be having an emergency, seek urgent help even if a symptom is not listed.','warning','warning')}</div>`;
if(formStep===1)content=`<h2>Let’s start with you.</h2><p>Basic information gives your health records context.</p><div class="form-grid">${inputField('name','Full name','','','',false,'text')}${inputField('age','Age','years',18,100,false)}${selectField('sex','Sex used for clinical equation',['Unknown','Female','Male'])}${inputField('height','Height','cm',80,250)}${inputField('weight','Weight','kg',20,350)}<div class="field"><label for="bmi-result">BMI <small>calculated automatically</small></label><input id="bmi-result" value="${bmi(draft.height,draft.weight)??'Unknown'}" readonly><span class="field-hint">Weight (kg) ÷ height (m)²</span></div></div>`;
if(formStep===2)content=`<h2>Cardiovascular measurements</h2><p>Enter your latest measurements. Leave unavailable values unknown.</p><div class="form-grid">${['systolic_bp','diastolic_bp','heart_rate'].map(k=>inputField(k,METRICS[k].label,METRICS[k].unit,METRICS[k].min,METRICS[k].max)).join('')}${inputField('recorded_at','Measurement date','','','',false,'date')}</div><div class="check-grid">${[['hypertension','Hypertension'],['previous_heart_disease','Previous heart disease'],['previous_stroke','Previous stroke'],['bp_treatment','Taking BP medication']].map(([k,l])=>checkField(k,l)).join('')}</div><div class="mt">${banner('For measurements taken on different dates, add each separately in Medical history.')}</div>`;
if(formStep===3)content=`<h2>Blood tests & kidney health</h2><p>Use the units shown. Unknown values are stored as missing, never as zero.</p><div class="form-grid">${['total_cholesterol','ldl','hdl','triglycerides','glucose','hba1c','creatinine','egfr','uacr'].map(k=>inputField(k,METRICS[k].label,METRICS[k].unit,METRICS[k].min,METRICS[k].max)).join('')}</div>`;
if(formStep===4)content=`<h2>Life beyond the numbers.</h2><p>These details supplement your records. They do not generate a clinical score.</p><div class="form-grid">${selectField('smoking','Smoking',['Unknown','Never','Former','Current'])}${selectField('alcohol','Alcohol use',['Unknown','None','Occasional','Regular'])}${selectField('activity','Physical activity',['Unknown','Low','Moderate','High'])}${selectField('exercise','Exercise frequency',['Unknown','0 days / week','1–2 days / week','3 days / week','4–5 days / week','6–7 days / week'])}${selectField('diet','Diet quality',['Unknown','Needs improvement','Balanced','Mostly heart-healthy'])}${inputField('sleep','Sleep duration','hours',0,24)}${selectField('stress','Stress level',['Unknown','Low','Moderate','High'])}</div><h3 class="mt">Reported medical history</h3><div class="check-grid">${[['diabetes','Diabetes'],['kidney_disease','Kidney disease'],['high_cholesterol','High cholesterol'],['heart_failure','Heart failure'],['previous_heart_attack','Previous heart attack'],['arrhythmia','Arrhythmia'],['family_history','Family history of CVD']].map(([k,l])=>checkField(k,l)).join('')}</div><div class="form-grid">${inputField('medications','Current medications','','','',false,'text')}${inputField('previous_medications','Previous medications','','','',true,'text')}${inputField('admissions','Hospital admissions','','','',true,'text')}${inputField('surgeries','Previous surgeries','','','',true,'text')}</div>`;
if(formStep===5){const e=preliminaryEligibility(draft);content=`<h2>Review your information.</h2><p>Confirm your entries before they are added to your health records.</p><div class="details-list"><div><span>Patient</span><strong>${esc(draft.name||'Unnamed')} · ${esc(draft.age||'Unknown')} years</strong></div><div><span>Measurement date</span><strong>${esc(draft.recorded_at||TODAY)}</strong></div>${['systolic_bp','diastolic_bp','ldl','hdl','hba1c','egfr'].map(k=>`<div><span>${METRICS[k].short}</span><strong>${numeric(draft[k])===null?'Unknown':`${fmt(draft[k])} ${METRICS[k].unit}`}</strong></div>`).join('')}<div><span>Calculated BMI</span><strong>${bmi(draft.height,draft.weight)??'Unknown'}</strong></div></div><div class="mt">${banner(`<strong>Risk estimate unavailable.</strong> ${e.reason} This prototype has no validated calculator or trained model. Saving your information will show your actual records and remove illustrative predictions.`)}</div><div class="mt">${banner('Entries are stored in this browser session only. Use fictional or de-identified data for this demonstration.','warning')}</div>`;}
return heading('A clearer picture starts here.','A guided health assessment, at your pace.')+`<div class="form-layout"><aside><div class="step-list">${steps.map((s,i)=>`<div class="step-item ${i===formStep?'active':i<formStep?'done':''}"><i>${i<formStep?'✓':i+1}</i><span>${s}</span></div>`).join('')}</div><div class="banner small mt">${icon('lock')}<div>Prototype session only.<br>Use fictional or de-identified records.</div></div></aside><form id="assessment-form" class="card form-card" novalidate>${content}<div id="form-error" class="form-error" role="alert"></div><div class="form-footer"><button type="button" class="btn" data-action="form-back" ${formStep===0?'disabled':''}>Back</button><span class="tiny muted">Step ${formStep+1} of ${steps.length}</span><button class="btn primary" type="submit">${formStep===5?'Save & view overview':'Continue'} ${icon('arrow')}</button></div></form></div>`;}
function reportContext(doctor=false){if(!doctor)return {patientName:name(),records:state.records,sample:state.sample,patientId:'personal',note:''};const p=patients.find(p=>p.id===activePatient)||patients[0];return {patientName:p.name,records:p.id==='p1'?sampleRecords():[],sample:true,patientId:p.id,note:state.notes[p.id]||''};}
function openPatient(id){activePatient=patients.some(p=>p.id===id)?id:'p1';state.selectedPatient=activePatient;persist();go(`patient-detail?patient=${activePatient}`);}
function saveRecords(records){const base=state.records.filter(r=>r.source!=='sample');validateBloodPressure([...base,...records]);state.records=[...base,...records];state.sample=false;}
function reports(doctor=false){const ctx=reportContext(doctor);return heading('Reports, ready for a conversation.','A structured summary of measurements, trends and limitations.',btn('Create current report','download','download',true))+`<div class="report-list"><article class="card report-item"><div class="report-symbol">${icon('file')}</div><div><h3>${doctor?esc(ctx.patientName):'Current health'} summary</h3><p>${ctx.sample?'Illustrative sample patient':'Browser-session records'} · ${ctx.records.length} measurements · No validated risk prediction</p></div>${badge('Ready to export','teal')}${btn('Download HTML','download','download')}${btn('Print / save PDF','print','file')}</article>${state.reports.map((r,i)=>({...r,index:i})).filter(r=>doctor?r.patient_id===activePatient:r.context!=='doctor').map(r=>`<article class="card report-item"><div class="report-symbol">${icon('file')}</div><div><h3>Health summary · ${esc(r.name)}</h3><p>Generated ${esc(new Date(r.created_at).toLocaleString('en-GB'))} · ${r.count} measurements</p></div>${btn('Download again',`saved-report-${r.index}`,'download')}</article>`).join('')}</div><section class="card card-pad mt"><h2>Share with your clinician</h2><p class="small muted mt">Download the summary and share it using your clinician’s preferred secure channel. The prototype does not send health records to another person.</p><div class="mt">${banner('Exports contain unverified entered records or sample data, and explicit model limitations. An export is not a diagnosis or a validated clinical risk report.')}</div></section><section class="card card-pad mt"><h2>Import a medical report</h2><p class="small muted mt">CSV and supported FHIR JSON observations can be reviewed before saving. PDF and image extraction need an OCR service, which is not connected.</p><div class="mt">${btn('Import & review measurements','upload','upload')}</div></section>`;}
function profile(){return heading('Your profile','Personal context for your cardiovascular history.',btn('Edit health information','assessment','edit',true))+`<div class="two-col"><section class="card card-pad"><div class="flex gap"><div class="avatar" style="width:56px;height:56px;font-size:17px">${initials()}</div><div><h2>${esc(name())}</h2><p class="small muted">${state.sample?'Illustrative patient profile':'Local session profile'}</p></div></div><div class="details-list">${[['Age',`${state.profile.age??'Unknown'} years`],['Sex',state.profile.sex||'Unknown'],['Height',state.profile.height?`${state.profile.height} cm`:'Unknown'],['Weight',state.profile.weight?`${state.profile.weight} kg`:'Unknown'],['BMI',bmi(state.profile.height,state.profile.weight)??'Unknown'],['Smoking',state.profile.smoking||'Unknown']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div></section><section class="card card-pad"><h2>Session & data controls</h2><p class="small muted mt">This interactive prototype uses temporary browser-session storage. It has no identity verification, server database or access enforcement between demo roles.</p><div class="details-list"><div><span>Session type</span><strong>${state.sample?'Sample demonstration':'Entered data'}</strong></div><div><span>Storage</span><strong>Current browser session</strong></div></div><div class="mt flex gap wrap">${btn('Load sample patient','load-sample','history')}${btn('Clear session data','clear-session','trash')}</div><p class="tiny muted mt">Clearing removes all entered records, notes and report history from this session.</p></section></div>`;}
function patientTable(filtered=patients){return `<div class="table-wrap"><table><thead><tr><th>PATIENT</th><th>SAMPLE RISK</th><th>TREND</th><th>CONFIDENCE</th><th>REVIEW</th><th></th></tr></thead><tbody>${filtered.map(p=>`<tr class="patient-row" data-patient="${p.id}" tabindex="0" role="button" aria-label="Open ${p.name}"><td><div class="patient-name"><div class="avatar">${p.initials}</div><div><strong>${p.name}</strong><p>${p.age} years · ${p.sex}</p></div></div></td><td><strong>${p.risk}%</strong> &nbsp;${badge(p.category,p.color)}</td><td class="${p.trend==='Increasing'?'':'muted'}">${icon(p.trend==='Increasing'?'up':'chart')} ${p.trend}</td><td class="muted">Not measured</td><td>${badge(p.review,p.review==='Required'?'amber':'neutral')}</td><td>${icon('chevron')}</td></tr>`).join('')||'<tr><td colspan="6">No patients match your filters.</td></tr>'}</tbody></table></div>`;}
function doctor(){const required=patients.filter(p=>p.review==='Required');return heading('A little context. Better care.','Your demonstration patient overview, at a glance.',btn('View all patients','patients','users',true))+sampleNotice()+`<div class="four-col mt">${[['Elevated or very high',patients.filter(p=>p.risk>=15).length,'amber'],['Moderate',patients.filter(p=>p.category==='Moderate').length,'blue'],['Low',patients.filter(p=>p.category==='Low').length,'teal'],['Review required',required.length,'amber']].map(([title,n,c])=>`<section class="card card-pad"><div class="stats-label">${title}</div><div class="stats-value">${n}</div><div class="mt">${badge('Sample patients',c)}</div></section>`).join('')}</div><section class="card records-card mt"><div class="card-title"><div><h2>Patients to look at first</h2><p>Sorted by illustrative risk, with review flags</p></div><a href="#/monitor" class="link-btn">Risk monitor ${icon('arrow')}</a></div>${patientTable([...patients].sort((a,b)=>b.risk-a.risk).slice(0,4))}</section><div class="two-col mt"><section class="card card-pad"><h2>Worsening trajectories</h2><p class="small muted mt">${patients.filter(p=>p.trend==='Increasing').length} sample patients have an increasing illustrative risk trajectory. Review longitudinal records alongside clinical context.</p><div class="mt">${btn('Inspect risk monitor','monitor','activity')}</div></section><section class="card card-pad"><h2>Model release status</h2><p class="small muted mt">No model is deployed. Sensitivity, calibration and subgroup performance have not been measured.</p><a href="#/models" class="link-btn mt">Open model performance ${icon('arrow')}</a></section></div>`;}
function patientList(monitor=false){let filtered=patients.filter(p=>(!monitor||p.trend==='Increasing')&&(doctorFilter==='all'||p.category===doctorFilter||p.review===doctorFilter)&&p.name.toLowerCase().includes(doctorSearch.toLowerCase()));filtered.sort((a,b)=>doctorSort==='name'?a.name.localeCompare(b.name):b.risk-a.risk);return heading(monitor?'Look closer at changing risk.':'Your patients, in perspective.',monitor?'Sample cases with an increasing trajectory.':'Search and prioritize the illustrative patient roster.')+sampleNotice()+`<div class="filter-row mt"><div class="search">${icon('search')}<input id="patient-search" placeholder="Search patients..." aria-label="Search patients" value="${esc(doctorSearch)}"></div><select id="patient-filter" aria-label="Filter patients">${[['all','All categories'],['Elevated','Elevated'],['Very high','Very high'],['Moderate','Moderate'],['Low','Low'],['Required','Review required']].map(([v,l])=>`<option value="${v}" ${doctorFilter===v?'selected':''}>${l}</option>`).join('')}</select><select id="patient-sort" aria-label="Sort patients"><option value="risk" ${doctorSort==='risk'?'selected':''}>Highest sample risk first</option><option value="name" ${doctorSort==='name'?'selected':''}>Name A–Z</option></select></div><section class="card">${patientTable(filtered)}</section><p class="tiny muted mt">Roster categories and risk values are fictional. Confidence and real model prioritization remain unavailable.</p>`;}
function patientDetail(){const p=patients.find(x=>x.id===activePatient)||patients[0];const exact=p.id==='p1';return heading(p.name,`${p.age} years · ${p.sex} · Demonstration patient ${p.id.toUpperCase()}`,`<a href="#/patients" class="btn">Back to patients</a>`+btn('Download summary','doctor-download','download'))+sampleNotice()+`<div class="three-col mt"><section class="card card-pad"><div class="stats-label">Illustrative risk</div><div class="stats-value">${p.risk}<small style="font-size:18px">%</small></div>${badge(p.category,p.color)}<p class="tiny muted mt">Fictional value, not a model prediction</p></section><section class="card card-pad"><div class="stats-label">Clinical calculator</div><div class="stats-value">—</div><h3>Not connected</h3><p class="tiny muted mt">No validated clinical score available</p></section><section class="card card-pad"><div class="stats-label">Clinical review</div><div class="stats-value" style="font-size:25px">${p.review}</div><p class="tiny muted mt">Sample workflow flag · confidence not measured</p></section></div><div class="two-col mt">${exact?chartCard('Patient measurement history',sampleRecords()):`<section class="card card-pad"><div class="empty">${icon('history')}<h3>Detailed history not included</h3><p>This sample case previews the roster workflow. Open Alex Morgan for the full five-year measurement example.</p>${btn('Open Alex Morgan','open-alex','user')}</div></section>`}<section class="card card-pad"><h2>Clinical notes</h2><p class="small muted" style="margin-top:5px">Session-only notes for this sample patient</p><textarea id="clinical-note" class="note-area" placeholder="Document your review, questions or follow-up considerations..." aria-label="Clinical note">${esc(noteDrafts[p.id]??state.notes[p.id]??'')}</textarea><div class="between mt"><span class="tiny muted">Use fictional or de-identified notes</span>${btn('Save note','save-note','check',true)}</div></section></div><div class="two-col mt"><section class="card card-pad"><h2>Record provenance & missing data</h2><div class="details-list"><div><span>Source</span><strong>Illustrative sample</strong></div><div><span>Verification</span><strong>Not clinically verified</strong></div><div><span>Model explanation</span><strong>Not generated</strong></div><div><span>Confidence</span><strong>Not measured</strong></div><div><span>Missing fields</span><strong>${exact?'Triglycerides, glucose, creatinine, UACR':'Detailed measurements unavailable'}</strong></div></div></section><section class="card card-pad"><h2>Interpretation boundaries</h2><p class="small muted mt">${exact?'Sample blood pressure, LDL and BMI increase over time. These trends are descriptive and do not establish a diagnosis.':'No underlying longitudinal measurements are included for this sample case.'}</p><p class="small muted mt">Treatment decisions require clinician evaluation. No validated risk, SHAP output, calibration result or predictive confidence is supplied.</p></section></div>`;}
function models(){const names=['AUROC','AUPRC','Sensitivity / recall','Specificity','Precision','F1 score','Brier score','False-negative rate'];return heading('Evidence before confidence.','Actual experimental results belong here. No model has been trained.')+banner('<strong>Release blocked: validation unavailable.</strong> The ≥95% sensitivity target is a validation requirement, not an achieved accuracy claim.','warning','shield')+`<div class="validation-grid">${names.map(n=>`<section class="card"><div class="stats-label">${n}</div><div class="stats-value">—</div><p class="tiny muted">Not evaluated</p></section>`).join('')}</div><div class="two-col"><section class="card card-pad"><h2>Model release gate</h2><div class="details-list"><div><span>Model version</span><strong>No trained version</strong></div><div><span>Safety target</span><strong>Sensitivity ≥95%</strong></div><div><span>Actual sensitivity</span><strong>Not measured</strong></div><div><span>Deployment status</span>${badge('Blocked','amber')}</div><div><span>Calibration</span><strong>Not evaluated</strong></div></div><p class="small muted mt">Sensitivity below the target rejects a release. Passing the target alone does not establish clinical readiness; calibration, false negatives and external validation also require review.</p></section><section class="card card-pad"><h2>A validation plan built for patients</h2><div class="details-list"><div><span>Dataset partitioning</span><strong>By patient, not measurement</strong></div><div><span>Baseline</span><strong>Logistic regression</strong></div><div><span>Primary comparison</span><strong>XGBoost · Random forest</strong></div><div><span>Long-term evaluation</span><strong>Survival models</strong></div><div><span>Interpretation</span><strong>Measured SHAP contributions</strong></div></div><p class="tiny muted mt">Training, model artifacts and evaluation services must be implemented before any real predictive results are displayed.</p></section></div>`;}
function versions(){return heading('Models with a paper trail.','Versioned, validated and traceable before deployment.')+`<section class="card table-wrap"><table><thead><tr><th>MODEL</th><th>PURPOSE</th><th>VERSION</th><th>VALIDATION</th><th>STATUS</th></tr></thead><tbody>${[['Logistic regression','Baseline'],['XGBoost','Primary research model'],['Random forest','Comparison model'],['Survival model','Long-term research']].map(([n,p])=>`<tr><td><strong>${n}</strong></td><td>${p}</td><td>—</td><td>Not evaluated</td><td>${badge('Planned','neutral')}</td></tr>`).join('')}</tbody></table></section><div class="mt">${banner('No trained artifacts or model versions are available. Sample dashboard values are independent of these planned models.')}</div>`;}
function auditPage(){return heading('A record of the work.','Activity from this browser session. This is not a server security audit log.')+`<section class="card table-wrap"><table class="audit-table"><thead><tr><th>TIME</th><th>ACTION</th><th>DETAILS</th></tr></thead><tbody>${state.audits.map(a=>`<tr><td class="muted">${esc(new Date(a.time).toLocaleString('en-GB'))}</td><td><strong>${esc(a.action)}</strong></td><td>${esc(a.detail)}</td></tr>`).join('')||'<tr><td colspan="3">No session activity yet. Save a measurement, import records or generate a report.</td></tr>'}</tbody></table></section>`;}
function evidence(){return heading('Built on transparency.','Understand what the prototype does today, and what needs validation.')+`<div class="two-col"><section class="card card-pad source-card"><h2>Clinical decision support</h2><p>CardioLens brings dated measurements into one view and calculates descriptive changes. Its interface demonstrates clinical and research risk outputs with explicitly fictional values.</p><p>The American Heart Association PREVENT 10-year equations are intended for adults aged 30–79 without known cardiovascular disease. This prototype performs only a preliminary age/history screen; the equation and its complete eligibility checks are not implemented.</p><a class="evidence-link" href="https://professional.heart.org/en/guidelines-and-statements/about-prevent-calculator" target="_blank" rel="noopener">American Heart Association · PREVENT ↗</a><a class="evidence-link" href="https://professional.heart.org/en/guidelines-and-statements/prevent-calculator" target="_blank" rel="noopener">Official PREVENT calculator ↗</a></section><section class="card card-pad source-card"><h2>Emergency symptoms come first</h2><p>Severe chest pain, severe shortness of breath or fainting pause the assessment before any risk calculation. These symptoms may require immediate medical evaluation.</p><p>The symptom check cannot diagnose or exclude an emergency. If you suspect an emergency, contact local emergency services. A long-term cardiovascular score does not assess acute symptoms.</p><a class="evidence-link" href="https://www.nhs.uk/conditions/heart-attack/" target="_blank" rel="noopener">NHS · Heart attack symptoms and urgent help ↗</a></section></div><section class="card card-pad mt"><h2>Prototype capabilities</h2><div class="details-list">${[['Available','Guided forms, dated records, trend charts, CSV/FHIR review, session notes and report export'],['Prediction','Unavailable — no clinical equation or trained ML model connected'],['Explainability','Observed trends only — no invented SHAP contributions'],['Authentication','Demo role switching only — not secure identity or role enforcement'],['Storage','Browser-session storage only — no clinical database or cloud document storage'],['Extraction','CSV and selected FHIR observations; PDF/image OCR unavailable'],['Performance','Not measured — ≥95% sensitivity is a target, never a guaranteed accuracy'],['Knowledge engine','Linked primary sources; RAG and LLM integration pending']].map(([k,v])=>`<div><span>${k}</span><span style="max-width:75%;text-align:right">${v}</span></div>`).join('')}</div></section>`;}
function auth(register=false){return `<div class="auth-wrap"><section class="card"><div class="eyebrow">CardioLens AI · Prototype access</div><h1 style="margin-top:10px">${register?'Start your health story.':'Welcome to CardioLens.'}</h1><p class="small muted mt">${register?'Create a profile for this browser session. Use fictional or de-identified information.':'Choose a workspace to explore. This demo does not verify credentials or provide secure clinical access.'}</p><form id="auth-form">${register?`<div class="field"><label for="auth-name">Profile name</label><input id="auth-name" name="name" placeholder="e.g. Alex Morgan" required maxlength="80"></div>`:''}<div class="field"><label for="auth-role">Workspace</label><select id="auth-role" name="role"><option value="patient">Patient</option><option value="doctor">Doctor demo</option><option value="admin">Model administration demo</option></select></div><button class="btn primary" type="submit">${register?'Create session profile':'Open workspace'} ${icon('arrow')}</button></form><div class="auth-tabs"><a href="#/${register?'login':'register'}">${register?'Explore an existing demo':'Create a session profile'}</a><a href="#/home">Back home</a></div></section></div>`;}
function render(){if(location.hash.startsWith('#/'))route=location.hash.slice(2).split('?')[0]||'dashboard';const selected=new URLSearchParams(location.hash.split('?')[1]||'').get('patient');if(selected&&patients.some(p=>p.id===selected))activePatient=selected;if(route==='features'){route='home';}if(['doctor','patients','monitor','patient-detail','doctor-reports'].includes(route)&&state.role!=='doctor'){state.role='doctor';persist();}if(['models','versions','audit'].includes(route)&&state.role!=='admin'){state.role='admin';persist();}if(['dashboard','assessment','history','timeline','risk','profile','reports'].includes(route)&&state.role!=='patient'){state.role='patient';persist();}const pages={dashboard,home,history,timeline,risk,assessment,reports,profile,doctor,patients:()=>patientList(false),monitor:()=>patientList(true),'patient-detail':patientDetail,'doctor-reports':()=>reports(true),models,versions,audit:auditPage,evidence,login:()=>auth(false),register:()=>auth(true)};const content=(pages[route]||dashboard)();document.getElementById('app').innerHTML=route==='home'?content:shell(content);document.title=`${route==='home'?'Your health, in perspective':route.replaceAll('-',' ')} · CardioLens AI`;bind();}
function go(path){if(location.hash===`#/${path}`)render();else location.hash=`#/${path}`;}
function prepareAssessment(){draft={...state.profile,sex:state.profile.sex?state.profile.sex.charAt(0).toUpperCase()+state.profile.sex.slice(1):'Unknown',recorded_at:state.profile.recorded_at||TODAY};for(const k of Object.keys(METRICS))draft[k]=state.sample?null:latest(k)?.value??null;if(numeric(state.profile.weight)!==null)draft.weight=state.profile.weight;draftSymptoms={};formStep=0;}
function collectForm(form){const inputs=form.querySelectorAll('input,select,textarea');for(const input of inputs){if(!input.name)continue;if(formStep===0){if(input.type==='checkbox')draftSymptoms[input.name]=input.checked;}else if(input.type==='checkbox')draft[input.name]=input.checked;else if(input.disabled)draft[input.name]=null;else draft[input.name]=input.type==='number'?numeric(input.value):input.value;}}
function formSubmit(event){event.preventDefault();const form=event.target;collectForm(form);if(emergency(draftSymptoms)){render();return;}const error=form.querySelector('#form-error');if(formStep===1){if(!draft.name?.trim()){error.textContent='Enter a profile name.';return;}if(numeric(draft.age)===null||!Number.isInteger(draft.age)||draft.age<18||draft.age>100){error.textContent='Enter a whole-number age between 18 and 100 for this adult prototype.';return;}}
for(const input of form.querySelectorAll('input[type=number]:not(:disabled)')){if(input.value!==''&&!input.checkValidity()){error.textContent=`Check ${form.querySelector(`label[for="${input.id}"]`)?.textContent||input.name}: enter a value between ${input.min} and ${input.max}.`;return;}}
if(formStep===2){if(!validDate(draft.recorded_at)){error.textContent=`Enter a measurement date on or before ${TODAY}.`;return;}if(numeric(draft.systolic_bp)!==null&&numeric(draft.diastolic_bp)!==null&&draft.systolic_bp<=draft.diastolic_bp){error.textContent='Systolic blood pressure must be higher than diastolic blood pressure.';return;}}
if(formStep===5){const additions=[];draft.bmi=bmi(draft.height,draft.weight);try{for(const key of Object.keys(METRICS)){if(numeric(draft[key])!==null)additions.push({...validateMeasurement({type:key,value:draft[key],unit:METRICS[key].unit,recorded_at:draft.recorded_at||TODAY,source:'manual',verified:false}),id:crypto.randomUUID()});}}catch(e){error.textContent=e.message;return;}validateBloodPressure(additions);state.records=state.records.filter(r=>r.source!=='sample'&&!additions.some(a=>a.type===r.type&&a.recorded_at===r.recorded_at&&r.source==='manual'));state.records.push(...additions);state.profile={...draft,name:draft.name.trim(),symptoms:{...draftSymptoms},symptoms_recorded_at:TODAY};state.sample=false;audit('Assessment saved',`${additions.length} confirmed measurements; prediction unavailable`);toast('Assessment saved. No risk score was generated.');go('dashboard');return;}formStep++;render();window.scrollTo({top:0,behavior:'smooth'});}
function modal(content){const d=document.querySelector('#modal');d.innerHTML=`<button class="icon-btn close-modal" data-close aria-label="Close dialog">${icon('close')}</button>${content}`;d.querySelector('[data-close]').onclick=()=>d.close();if(!d.open)d.showModal();}
function addRecord(id){const existing=state.records.find(r=>r.id===id);modal(`<h2>${existing?'Edit':'Add'} a measurement</h2><p class="small muted mt">Every record keeps its value, unit, date and source.</p>${state.sample?banner('Saving a measurement exits the sample demonstration and removes the fictional records.'):''}<form id="record-form"><div class="form-grid"><div class="field full-span"><label for="record-type">Measurement</label><select id="record-type" name="type">${Object.entries(METRICS).map(([k,v])=>`<option value="${k}" ${existing?.type===k?'selected':''}>${v.label} (${v.unit})</option>`).join('')}</select></div><div class="field"><label for="record-value">Value</label><input id="record-value" name="value" type="number" step="any" value="${existing?.value??''}" required></div><div class="field"><label for="record-date">Recorded on</label><input id="record-date" name="recorded_at" type="date" value="${existing?.recorded_at||TODAY}" max="${TODAY}" required></div><p class="field-hint full-span">All entries are patient-reported and marked unverified. Use the unit displayed for the selected measurement.</p></div><div id="record-error" class="form-error" role="alert"></div><div class="form-footer"><button type="button" class="btn" data-cancel>Cancel</button><button type="submit" class="btn primary">${existing?'Save changes':'Save measurement'}</button></div></form>`);document.querySelector('[data-cancel]').onclick=()=>document.querySelector('#modal').close();document.querySelector('#record-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const record=validateMeasurement({...data,unit:METRICS[data.type].unit,source:existing?.source||'manual',verified:false});record.id=existing?.id||crypto.randomUUID();if(existing){const updated=state.records.map(r=>r.id===id?record:r);validateBloodPressure(updated);state.records=updated;}else saveRecords([record]);audit(existing?'Measurement edited':'Measurement saved',`${record.type} · ${record.recorded_at}`);document.querySelector('#modal').close();toast('Measurement saved as unverified.');render();}catch(err){document.querySelector('#record-error').textContent=err.message;}};}
function inspect(id){const r=state.records.find(r=>r.id===id)||sampleRecords().find(r=>r.id===id);if(!r)return;modal(`<div class="eyebrow">Record details</div><h2 style="margin-top:8px">${METRICS[r.type].label}</h2><div class="stats-value">${fmt(r.value)} <span class="small muted">${esc(r.unit)}</span></div><div class="details-list"><div><span>Recorded on</span><strong>${dateLabel(r.recorded_at)}</strong></div><div><span>Source</span><strong>${esc(r.source)}</strong></div><div><span>Clinically verified</span>${badge('No','neutral')}</div><div><span>Record ID</span><span class="tiny">${esc(r.id)}</span></div></div><p class="small muted mt">${r.source==='sample'?'This is a fictional measurement for demonstration.':'Patient-reported or imported measurement. A clinician has not verified this value.'}</p>`);}
function upload(){staged=[];modal(`<h2>Import. Review. Confirm.</h2><p class="small muted mt">Measurements are never added without your confirmation.</p><div class="upload-zone">${icon('upload')}<h3>Bring your records together</h3><p>CSV · FHIR JSON · PDF · JPG / PNG<br>Maximum 5 MB per file</p><label class="btn primary" for="import-file">Choose a file ${icon('upload')}</label><input id="import-file" type="file" accept=".csv,.json,.pdf,.png,.jpg,.jpeg"></div><div id="import-status" class="form-error" role="alert"></div><div class="mt">${banner('CSV and selected FHIR observations can be parsed here. PDF/image OCR is not connected; those measurements must be entered manually.')}</div><button class="link-btn mt" data-template>Download example CSV ${icon('download')}</button>`);document.querySelector('[data-template]').onclick=()=>downloadFile('cardiolens-records-template.csv','type,value,unit,recorded_at\nldl,145,mg/dL,2025-04-14\nhdl,43,mg/dL,2025-04-14\nhba1c,6.4,%,2025-04-14\n','text/csv');document.querySelector('#import-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const status=document.querySelector('#import-status');if(file.size>5*1024*1024){status.textContent='Choose a file under 5 MB.';return;}if(!/\.(csv|json)$/i.test(file.name)){status.textContent='PDF/image extraction is unavailable. No file was uploaded or stored. Add the measurements manually.';return;}try{const text=await file.text();staged=file.name.toLowerCase().endsWith('.csv')?parseCSV(text):parseFHIR(JSON.parse(text));reviewImport(file.name);}catch(err){status.textContent=err.message;}};}
function reviewImport(fileName){modal(`<h2>Review extracted measurements</h2><p class="small muted mt">${esc(fileName)} · ${staged.length} measurements. Edit any values before confirming.</p>${state.sample?banner('Confirming this import exits the sample demonstration and removes fictional records.'):''}<div class="table-wrap mt" style="max-height:340px"><table><thead><tr><th>MEASUREMENT</th><th>VALUE</th><th>DATE</th><th></th></tr></thead><tbody>${staged.map((r,i)=>`<tr><td>${METRICS[r.type].short}<p class="tiny muted">${esc(r.unit)}</p></td><td><input style="width:85px" data-stage-value="${i}" type="number" step="any" aria-label="${METRICS[r.type].short} value" value="${r.value}"></td><td><input style="width:133px" type="date" data-stage-date="${i}" aria-label="Recorded date for ${METRICS[r.type].short}" max="${TODAY}" value="${r.recorded_at}"></td><td><button class="icon-btn" data-remove-stage="${i}" aria-label="Remove ${METRICS[r.type].short}">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div><div id="import-error" class="form-error" role="alert"></div><div class="form-footer"><button class="btn" data-cancel-import>Discard</button><button class="btn primary" data-confirm-import ${!staged.length?'disabled':''}>Confirm ${staged.length} measurements ${icon('check')}</button></div>`);const collect=()=>{document.querySelectorAll('[data-stage-value]').forEach(el=>staged[Number(el.dataset.stageValue)].value=numeric(el.value));document.querySelectorAll('[data-stage-date]').forEach(el=>staged[Number(el.dataset.stageDate)].recorded_at=el.value);};document.querySelectorAll('[data-remove-stage]').forEach(el=>el.onclick=()=>{collect();staged.splice(Number(el.dataset.removeStage),1);reviewImport(fileName);});document.querySelector('[data-cancel-import]').onclick=()=>{staged=[];document.querySelector('#modal').close();};document.querySelector('[data-confirm-import]').onclick=()=>{collect();try{const approved=staged.map(r=>({...validateMeasurement(r),id:crypto.randomUUID()}));saveRecords(approved);audit('Import confirmed',`${approved.length} unverified measurements`);staged=[];document.querySelector('#modal').close();toast('Reviewed measurements added to history.');go('history');}catch(e){document.querySelector('#import-error').textContent=e.message;}};}
function downloadFile(filename,content,mime='text/html'){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function reportHTML(patientName=name(),records=state.records,isSample=state.sample,note=''){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CardioLens · ${esc(patientName)} health summary</title><style>body{font:14px/1.7 system-ui,sans-serif;color:#203744;max-width:980px;margin:40px auto;padding:20px}h1{font-size:28px}h2{font-size:19px}.notice{padding:18px;background:#f4f7f7;border:1px solid #dbe4e6;border-radius:8px;margin:20px 0}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:9px;border-bottom:1px solid #e4ebed}th{background:#f6f8f9}small{color:#6c808a}button{padding:10px 16px}@media print{button{display:none}body{margin:0}tr{break-inside:avoid}}</style></head><body><small>CARDIOLENS AI · CLINICAL DECISION-SUPPORT PROTOTYPE</small><h1>${esc(patientName)} · Health summary</h1><p>Generated ${esc(new Date().toLocaleString('en-GB'))} · ${records.length} measurements</p><div class="notice"><strong>${isSample?'Illustrative sample patient — not a medical assessment.':'Patient-entered or imported data — unverified.'}</strong><p>No validated clinical risk, ML probability, SHAP explanation or model confidence is available. Sample risk numbers are not included as patient results. This report must not guide treatment or assess emergency symptoms.</p></div><h2>Observed longitudinal changes</h2><table><thead><tr><th>Measurement</th><th>Earlier</th><th>Latest</th><th>Change</th></tr></thead><tbody>${['systolic_bp','ldl','bmi','hba1c'].map(k=>{const t=trend(records,k);return `<tr><td>${METRICS[k].label}</td><td>${t?`${t.base.value} (${t.base.recorded_at})`:'Insufficient data'}</td><td>${t?`${t.latest.value} (${t.latest.recorded_at})`:'—'}</td><td>${t?`${t.change>0?'+':''}${t.change} ${METRICS[k].unit}`:'—'}</td></tr>`;}).join('')}</tbody></table><h2>Recorded measurements</h2><table><thead><tr><th>Measurement</th><th>Value</th><th>Unit</th><th>Date</th><th>Source</th><th>Verified</th></tr></thead><tbody>${[...records].sort((a,b)=>b.recorded_at.localeCompare(a.recorded_at)).map(r=>`<tr><td>${METRICS[r.type]?.label||esc(r.type)}</td><td>${esc(r.value)}</td><td>${esc(r.unit)}</td><td>${esc(r.recorded_at)}</td><td>${esc(r.source)}</td><td>No</td></tr>`).join('')}</tbody></table>${note?`<h2>Clinical note</h2><p>${esc(note).replace(/\n/g,'<br>')}</p>`:''}<h2>Evidence & limitations</h2><p>PREVENT eligibility requires full clinical input validation. This prototype does not implement the equation. Model performance is unmeasured; sensitivity ≥95% is an intended validation target only.</p><p><a href="https://professional.heart.org/en/guidelines-and-statements/about-prevent-calculator">AHA PREVENT</a> · <a href="https://www.nhs.uk/conditions/heart-attack/">NHS emergency symptoms</a></p><p>For emergency symptoms, contact local emergency services. Do not rely on this report for urgent medical decisions.</p><button onclick="window.print()">Print / save as PDF</button></body></html>`;}
function generateReport(doctorPatient=false){const ctx=reportContext(doctorPatient);const html=reportHTML(ctx.patientName,ctx.records,ctx.sample,ctx.note);downloadFile(`CardioLens-${ctx.patientName.replace(/[^a-z0-9]/gi,'-')}-summary.html`,html);state.reports.unshift({name:ctx.patientName,patient_id:ctx.patientId,context:doctorPatient?'doctor':'patient',count:ctx.records.length,created_at:new Date().toISOString(),html});audit('Report generated',`${ctx.records.length} measurements; ${ctx.sample?'sample':'unverified entered data'}`);toast('Summary downloaded. Open it to print or save as PDF.');if(['reports','doctor-reports'].includes(route))render();}
function confirmClear(sample=false){modal(`<h2>${sample?'Load the sample patient?':'Clear this session?'}</h2><p class="small muted mt">This replaces your profile, records, notes and export history in this browser session. Download any information you want to keep first.</p><div class="form-footer"><button class="btn" data-keep>Keep current data</button><button class="btn primary" data-reset>${sample?'Load sample':'Clear session'}</button></div>`);document.querySelector('[data-keep]').onclick=()=>document.querySelector('#modal').close();document.querySelector('[data-reset]').onclick=()=>{state=sample?defaultState():{...defaultState(),sample:false,profile:{name:'Your profile'},records:[],reports:[],audits:[],notes:{}};noteDrafts={};activePatient='p1';metric='systolic_bp';period=5;selectedYear=2026;historyFilter='all';doctorFilter='all';doctorSearch='';doctorSort='risk';persist();document.querySelector('#modal').close();prepareAssessment();toast(sample?'Sample patient loaded.':'Session data cleared.');go('dashboard');};}
function action(key){if(key==='assessment'){prepareAssessment();go('assessment');}else if(['patients','monitor'].includes(key))go(key);else if(key==='add-record')addRecord();else if(key==='upload')upload();else if(key==='download')generateReport(route==='doctor-reports');else if(key==='doctor-download')generateReport(true);else if(key==='print'){const report=window.open('', '_blank');if(report){report.document.open();const ctx=reportContext(route==='doctor-reports');report.document.write(reportHTML(ctx.patientName,ctx.records,ctx.sample,ctx.note));report.document.close();report.focus();report.print();}else toast('Allow a report window, or download HTML and print it.');}else if(key==='account')go('login');else if(key==='load-sample')confirmClear(true);else if(key==='clear-session')confirmClear(false);else if(key==='save-note'){const value=document.querySelector('#clinical-note').value.trim();state.notes[activePatient]=value;delete noteDrafts[activePatient];audit('Clinical note saved',`Sample patient ${activePatient}`);toast('Note saved for this browser session.');}else if(key==='open-alex'){openPatient('p1');}else if(key==='review-symptoms'){draftSymptoms={};formStep=0;render();}else if(key==='form-back'){collectForm(document.querySelector('#assessment-form'));formStep=Math.max(0,formStep-1);render();}else if(key==='notifications')modal(`<h2>Workspace updates</h2><div class="details-list"><div><span>Prediction service</span><strong>Not connected</strong></div><div><span>Model validation</span><strong>Pending</strong></div><div><span>Record completeness</span><strong>${completeness().percent}%</strong></div></div><p class="small muted mt">Updates reflect this demonstration session.</p>`);else if(key==='open-nav'){document.querySelector('.sidebar').classList.add('open');document.querySelector('.mobile-overlay').classList.add('open');}else if(key==='close-nav'){document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-overlay').classList.remove('open');}else if(key.startsWith('saved-report-')){const r=state.reports[Number(key.split('-').at(-1))];if(r)downloadFile('CardioLens-saved-summary.html',r.html);}}
function bind(){document.querySelector('#clinical-note')?.addEventListener('input',e=>{noteDrafts[activePatient]=e.target.value;});const skip=document.querySelector('.skip');if(skip)skip.onclick=e=>{e.preventDefault();const main=document.querySelector('#main');main?.focus();main?.scrollIntoView({behavior:'smooth'});};document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelector('#role-switch')?.addEventListener('change',e=>{state.role=e.target.value;persist();go(state.role==='patient'?'dashboard':state.role==='doctor'?'doctor':'models');});document.querySelector('#chart-metric')?.addEventListener('change',e=>{metric=e.target.value;render();});document.querySelectorAll('[data-period]').forEach(el=>el.onclick=()=>{period=Number(el.dataset.period);render();});document.querySelectorAll('[data-year]').forEach(el=>el.onclick=()=>{selectedYear=Number(el.dataset.year);render();});document.querySelector('#history-filter')?.addEventListener('change',e=>{historyFilter=e.target.value;render();});document.querySelectorAll('[data-record],[data-inspect]').forEach(el=>{el.onclick=()=>inspect(el.dataset.record||el.dataset.inspect);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(el.dataset.record||el.dataset.inspect);}};});document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>addRecord(el.dataset.edit));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>{const id=el.dataset.delete;modal(`<h2>Remove this measurement?</h2><p class="small muted mt">The entry will be removed from this session’s history.</p><div class="form-footer"><button class="btn" data-keep>Keep measurement</button><button class="btn danger" data-remove>Remove</button></div>`);document.querySelector('[data-keep]').onclick=()=>document.querySelector('#modal').close();document.querySelector('[data-remove]').onclick=()=>{state.records=state.records.filter(r=>r.id!==id);audit('Measurement removed',id);document.querySelector('#modal').close();render();};});document.querySelectorAll('[data-patient]').forEach(el=>{el.onclick=()=>{openPatient(el.dataset.patient);};el.onkeydown=e=>{if(e.key==='Enter')el.click();};});document.querySelector('#patient-filter')?.addEventListener('change',e=>{doctorFilter=e.target.value;render();});document.querySelector('#patient-sort')?.addEventListener('change',e=>{doctorSort=e.target.value;render();});document.querySelector('#patient-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;doctorSearch=e.target.value;render();const input=document.querySelector('#patient-search');input.focus();input.setSelectionRange(pos,pos);});document.querySelector('#assessment-form')?.addEventListener('submit',formSubmit);document.querySelectorAll('[data-unknown]').forEach(el=>el.onchange=()=>{const input=document.getElementById(el.dataset.unknown);input.disabled=el.checked;if(el.checked){input.value='';draft[el.dataset.unknown]=null;}if(['height','weight'].includes(el.dataset.unknown)){const h=document.querySelector('#height'),w=document.querySelector('#weight'),out=document.querySelector('#bmi-result');if(out)out.value=bmi(h?.disabled?null:h?.value,w?.disabled?null:w?.value)??'Unknown';}});if(formStep===0){document.querySelectorAll('#assessment-form input[type=checkbox]').forEach(el=>el.onchange=()=>{collectForm(document.querySelector('#assessment-form'));if(emergency(draftSymptoms)){render();window.scrollTo(0,0);}});}['height','weight'].forEach(key=>document.getElementById(key)?.addEventListener('input',()=>{const output=document.querySelector('#bmi-result');if(output)output.value=bmi(document.querySelector('#height').value,document.querySelector('#weight').value)??'Unknown';}));document.querySelector('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));state.role=values.role;if(values.name!==undefined){if(!values.name.trim()){toast('Enter a profile name.');return;}values.name=values.name.trim();state={...defaultState(),role:values.role,sample:false,profile:{name:values.name},records:[]};noteDrafts={};activePatient='p1';historyFilter='all';persist();prepareAssessment();go(values.role==='patient'?'assessment':values.role==='doctor'?'doctor':'models');}else{persist();go(values.role==='patient'?'dashboard':values.role==='doctor'?'doctor':'models');}});}
window.addEventListener('hashchange',()=>{if(location.hash==='#/assessment'&&route!=='assessment')prepareAssessment();if(location.hash==='#features'){location.hash='#/home';setTimeout(()=>document.querySelector('#features')?.scrollIntoView({behavior:'smooth'}),100);return;}render();window.scrollTo(0,0);});
document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
prepareAssessment();try{thresholds=await fetch('risk_thresholds.json').then(r=>r.json());for(const p of patients){const band=thresholds.bands.find(b=>p.risk/100>=b.min&&p.risk/100<b.max);p.category=band?.label||'Uncategorized';}}catch{}render();
